import {PRIORITIES,openItem} from './domain.js';
import {PlanningPreferences,PLANNING_KEY,EVENT_COLORS,dueReminders,postpone,reminderDate,calendarEvent,calendarTemplate,validClientId,validZone} from './planning.js';
import {GoogleCalendarAdapter,createGoogleSession} from './google-calendar.js';
import {checkForm,submitOnce} from './forms.js';
export function createPlanningUI({storage,getState,icon,esc,openModal,closeModal,toast,onOpen,onEdit,onComplete,target=window,now=()=>new Date(),googleSession,adapter,appUrl=new URL('./',target.location.href).href}){
  const preferences=new PlanningPreferences(storage),busy=new Set();let visible=60,calendars=[],timer;
  const prefs=()=>preferences.value;
  const session=googleSession||createGoogleSession({target,onChange:()=>refresh()});
  const google=adapter||new GoogleCalendarAdapter({token:session.token,onUnauthorized:()=>session.invalidate()});
  const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
  const check=(id,label,checked)=>`<label class="planning-check" for="${id}"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`;
  const items=()=>dueReminders(getState(),prefs(),now());
  function header(){const list=items();return `<button type="button" class="reminder-trigger" data-action="planning-open" aria-label="Lembretes: ${list.length} ${list.length===1?'prazo próximo ou atrasado':'prazos próximos ou atrasados'}" title="Lembretes">${icon('bell')}${list.length?`<span class="reminder-count" aria-hidden="true">${list.length>99?'99+':list.length}</span>`:''}</button>`}
  function summaryContent(){const list=items();if(!list.length)return '';const late=list.filter(x=>x.overdue).length,today=list.filter(x=>x.group==='today').length;return `<button class="reminder-summary" data-action="planning-open">${icon('bell')}<span><strong>${list.length} ${list.length===1?'prazo para acompanhar':'prazos para acompanhar'}</strong><small>${[late?late+' em atraso':'',today?today+' para hoje':'',list.length-late-today?list.length-late-today+' próximos':''].filter(Boolean).join(' · ')}</small></span>${icon('right')}</button>`}
  const summary=()=>`<div id="planning-summary">${summaryContent()}</div>`;
  function calendarButton(t){return `<button type="button" class="calendar-action priority-${t.priority}" data-action="planning-calendar" data-id="${esc(t.id)}" aria-label="${t.date?'Enviar ao Google Agenda: ':'Definir data para enviar ao Google Agenda: '}${esc(t.title)}" title="${t.date?'Google Agenda':'Defina uma data para enviar ao Google Agenda'}" aria-busy="${busy.has(t.id)}" ${busy.has(t.id)?'disabled':''}>${icon('calendar-plus')}</button>`}
  function reminderRows(){const list=items(),show=list.slice(0,visible),state=getState();if(!prefs().reminders.enabled)return `<div class="empty"><h2>Lembretes desativados</h2><p>Ative os avisos para acompanhar os prazos dos seus itens e subitens.</p><button class="btn primary" data-action="planning-reminder-settings">Configurar lembretes</button></div>`;
    if(!list.length)return `<div class="empty"><span class="emptyicon">${icon('bell')}</span><h2>Nenhum prazo para lembrar agora</h2><p>Itens e subitens em aberto aparecem aqui de acordo com suas próprias datas. Concluídos, cancelados e itens sem data ficam fora dos avisos.</p><button class="btn secondary" data-action="planning-reminder-settings">Ajustar lembretes</button></div>`;
    return `<div class="reminder-list">${show.map(entry=>{const t=entry.item,p=PRIORITIES.find(x=>x.id===t.priority),parent=t.parentId?state.items[t.parentId]:null;return `<article class="reminder-card priority-${t.priority}"><div class="reminder-card-head"><span class="reminder-date ${entry.overdue?'late':''}">${icon('clock')}${esc(reminderDate(entry,now(),prefs().calendar.timeZone))}</span><span class="reminder-priority">${p.symbol} ${p.label}</span></div><button class="reminder-title" data-action="planning-edit" data-id="${esc(t.id)}">${esc(t.title)}</button><p class="reminder-context">${t.parentId?'Subitem':'Item'} · ${esc(state.areas[t.areaId]?.name)}${parent?'<br>Em: '+esc(parent.title):''}</p><div class="reminder-actions"><button class="textbtn" data-action="planning-complete" data-id="${esc(t.id)}">${icon('check')} Concluir</button><button class="textbtn" data-action="planning-calendar" data-id="${esc(t.id)}" ${busy.has(t.id)?'disabled':''}>${icon('calendar-plus')} Google Agenda</button><button class="textbtn" data-action="planning-snooze" data-id="${esc(t.id)}">${icon('clock')} Adiar ${prefs().reminders.snoozeMinutes<60?prefs().reminders.snoozeMinutes+' min':prefs().reminders.snoozeMinutes/60+' h'}</button><button class="textbtn" data-action="planning-dismiss" data-id="${esc(t.id)}">Dispensar hoje</button></div></article>`}).join('')}</div>${list.length>visible?`<div class="collection-more"><p>${visible} de ${list.length} lembretes</p><button class="btn secondary" data-action="planning-more">Mostrar mais 60</button></div>`:''}`;
  }
  function page(){return `<div class="page-heading"><div><h1>Lembretes</h1><p>Datas primeiro, com o horário e a prioridade de cada etapa.</p></div></div><div class="reminder-toolbar"><button class="textbtn" data-action="page" data-page="plan">${icon('left')} Planejamento</button><button class="textbtn" data-action="planning-reminder-settings">${icon('settings')} Configurar</button></div><div id="reminders-results">${reminderRows()}</div>`}
  function connectionMessage(){const c=prefs().calendar,s=session.snapshot();return c.mode==='web'?'O botão abre o evento preenchido. Confirme em Salvar no Google Agenda. As cores e os avisos seguem as opções escolhidas no Google.':s.message||(s.connected?'Conectado nesta sessão.':'Conecte ao Google para adicionar com cores e avisos por prioridade.')}
  function settings(){const r=prefs().reminders,c=prefs().calendar,s=session.snapshot();return `${preferences.error?`<p class="planning-warning" role="status">${esc(preferences.error)}</p>`:''}<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('bell')}</span><div><h2>Lembretes de tarefas</h2><p>${r.enabled?'Hoje'+(r.aheadDays?' e os próximos '+r.aheadDays+' dias':'')+(r.overdue?', incluindo atrasados.':'.'):'Avisos desativados neste aparelho.'}</p></div></div><p>Os avisos aparecem ao abrir e usar o Retomar. Itens e subitens usam seus próprios prazos.</p><button class="btn secondary" data-action="planning-reminder-settings">Configurar lembretes ${icon('arrow')}</button></section><section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('calendar-plus')}</span><div><h2>Google Agenda</h2><p>Envie cada item ou subitem pelo botão de calendário.</p></div></div><p data-google-message role="status">${esc(connectionMessage())}</p><div class="calendar-colors" aria-label="Cores configuradas para o envio direto">${PRIORITIES.map(p=>`<span><i style="--event-color:${EVENT_COLORS.find(([id])=>id===c.colors[p.id])[2]}"></i>${p.label}</span>`).join('')}</div><p class="field-help">${c.duration} min para eventos com horário · ${c.undatedTime==='allDay'?'Sem horário: dia inteiro':'Sem horário: '+esc(c.defaultTime)}<br>Fuso: ${esc(c.timeZone)}</p><div class="settings-buttons calendar-settings-buttons"><button class="btn secondary" data-action="planning-calendar-settings">Configurar adições ${icon('arrow')}</button>${c.mode==='direct'?`<button class="btn primary" data-action="planning-connect" data-google-connect ${['loading','authorizing'].includes(s.phase)?'disabled':''}>${s.connected?'Reconectar ao Google':s.phase==='loading'?'Preparando…':'Conectar ao Google'}</button>`:''}</div><button class="textbtn" data-action="planning-disconnect" data-google-disconnect ${s.connected?'':'hidden'}>Desconectar do Google neste aparelho</button><details class="settings-details"><summary>Como funciona a adição?</summary><p>O modo Abrir no Google Agenda prepara um evento e pede a confirmação de salvamento no Google. Para adicionar diretamente com cores e avisos configurados aqui, escolha Envio direto e autorize o Google uma vez nesta sessão. Reenviar o mesmo item à mesma agenda atualiza o evento vinculado; isso não é uma sincronização automática com a agenda. A conclusão no Retomar não exclui o evento do Google.</p></details></section>`}
  function save(next){preferences.save(next);refresh();return next}
  function reminderSettings(){const r=prefs().reminders,root=openModal('Configurar lembretes',`<form id="reminder-settings-form"><div class="formerror" role="alert"></div>${check('reminders-enabled','Mostrar lembretes dentro do Retomar',r.enabled)}<div class="field"><label for="reminders-days">Antecedência por data</label><select id="reminders-days">${[[0,'Somente hoje'],[1,'Hoje e amanhã'],[3,'Próximos 3 dias'],[7,'Próximos 7 dias'],[14,'Próximos 14 dias'],[30,'Próximos 30 dias']].map(([v,l])=>option(v,l,r.aheadDays)).join('')}</select></div>${check('reminders-overdue','Incluir tarefas atrasadas',r.overdue)}<div class="field"><label for="reminders-snooze">Adiar um aviso por</label><select id="reminders-snooze">${[[15,'15 minutos'],[30,'30 minutos'],[60,'1 hora'],[180,'3 horas'],[1440,'24 horas']].map(([v,l])=>option(v,l,r.snoozeMinutes)).join('')}</select></div><p class="field-help">A data e o horário vêm antes da prioridade na ordem dos avisos. Um item sem horário fica atrasado após o fim da sua data. Dispensar hoje oculta apenas o aviso; a tarefa permanece no planejamento. Alertas com o Retomar fechado dependem dos avisos do Google Agenda.</p><button class="textbtn" type="button" id="clear-reminder-dismissals">Limpar adiamentos e avisos dispensados</button><div class="dialogactions"><button class="btn secondary" type="button" id="cancel-planning-settings">Cancelar</button><button class="btn primary" type="submit">Salvar lembretes</button></div><p class="field-help save-note">Preferências salvas neste aparelho.</p></form>`);
    let clear=false;root.querySelector('#clear-reminder-dismissals').onclick=e=>{clear=true;e.target.textContent='Avisos serão reativados ao salvar.';root.querySelector('#reminders-enabled').dispatchEvent(new Event('change',{bubbles:true}))};root.querySelector('#cancel-planning-settings').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{try{if(!checkForm(e.target))return;const next=structuredClone(prefs());next.reminders={enabled:root.querySelector('#reminders-enabled').checked,aheadDays:Number(root.querySelector('#reminders-days').value),overdue:root.querySelector('#reminders-overdue').checked,snoozeMinutes:Number(root.querySelector('#reminders-snooze').value)};if(clear)next.dismissals={};save(next);closeModal(true);toast('Lembretes configurados neste aparelho.');onOpen?.(false)}catch(error){root.querySelector('.formerror').textContent=error.message}});
  }
  function calendarSettings(){const c=prefs().calendar,choices=[{id:'primary',name:'Agenda principal'},...calendars.filter(x=>!x.primary)];if(!choices.some(x=>x.id===c.calendarId))choices.push({id:c.calendarId,name:'Agenda escolhida anteriormente'});
    const root=openModal('Configurar Google Agenda',`<form id="calendar-settings-form"><div class="formerror" role="alert"></div><div class="field"><label for="calendar-mode">Como adicionar</label><select id="calendar-mode">${option('web','Abrir no Google Agenda',c.mode)}${option('direct','Envio direto com cores',c.mode)}</select><small class="field-help">Abrir prepara o evento para você salvar no Google. O envio direto exige a conexão abaixo.</small></div><div class="field"><label for="calendar-target">Agenda de destino</label><select id="calendar-target" data-full-value>${choices.map(x=>option(x.id,x.name,c.calendarId)).join('')}</select><small class="field-help">Conecte ao Google para escolher entre as agendas que pertencem à sua conta.</small></div><div class="fieldsrow"><div class="field"><label for="calendar-duration">Duração dos eventos com horário</label><select id="calendar-duration">${[15,30,45,60,90,120,180].map(v=>option(v,v+' minutos',c.duration)).join('')}</select></div><div class="field"><label for="calendar-no-time">Quando o item não tem horário</label><select id="calendar-no-time">${option('allDay','Evento de dia inteiro',c.undatedTime)}${option('defaultTime','Usar horário padrão',c.undatedTime)}</select></div></div><div class="field"><label for="calendar-default-time">Horário padrão</label><input type="time" id="calendar-default-time" step="60" value="${esc(c.defaultTime)}"></div><div class="field"><label for="calendar-zone">Fuso horário dos prazos e eventos</label><input id="calendar-zone" required maxlength="100" autocomplete="off" spellcheck="false" value="${esc(c.timeZone)}" placeholder="America/Sao_Paulo"><small class="field-help">Por exemplo, America/Sao_Paulo, America/Manaus, Europe/Lisbon ou UTC. Também define os dias dos lembretes.</small></div>${check('calendar-notes','Incluir as observações no evento',c.includeNotes)}${check('calendar-priority-title','Incluir a prioridade no título do evento',c.priorityTitle)}<fieldset class="planning-fieldset"><legend>Opções do envio direto</legend><p class="field-help">Cores e avisos automáticos são aplicados após conectar ao Google. No modo Abrir, escolha essas opções no próprio Google Agenda.</p><div class="field"><label for="calendar-notification">Aviso do Google Agenda</label><select id="calendar-notification">${[['default','Padrão da agenda'],['none','Sem aviso'],['0','Na hora do evento'],['5','5 minutos antes'],['10','10 minutos antes'],['15','15 minutos antes'],['30','30 minutos antes'],['60','1 hora antes'],['1440','1 dia antes']].map(([v,l])=>option(v,l,c.notification)).join('')}</select><small class="field-help">Em eventos de dia inteiro, o Google conta a antecedência a partir do início desse dia.</small></div><div class="calendar-priority-fields">${PRIORITIES.map(p=>`<div class="field"><label for="calendar-color-${p.id}">${p.symbol} ${p.label}</label><select id="calendar-color-${p.id}">${EVENT_COLORS.map(([id,name])=>option(id,name,c.colors[p.id])).join('')}</select></div>`).join('')}</div><p class="field-help">Escolha quatro cores diferentes para distinguir as prioridades.</p></fieldset><details class="settings-details" id="google-setup"><summary>Preparar a conexão direta uma vez</summary><p>O Retomar precisa de um ID público de cliente OAuth próprio. Não é senha, token do GitHub nem segredo do cliente.</p><ol><li>No <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer">Google Cloud</a>, crie ou selecione um projeto e ative a Google Calendar API.</li><li>Configure a tela de consentimento. Se o projeto estiver em teste, adicione sua conta como usuária de teste.</li><li>Crie um cliente OAuth do tipo Aplicativo da Web. Em Origens JavaScript autorizadas, adicione <strong>https://sosoft142.github.io</strong>.</li><li>Cole o ID público abaixo, escolha Envio direto, salve e toque em Conectar ao Google. Não precisa informar segredo do cliente nem chave de API.</li></ol><p>O acesso autorizado é para eventos das agendas que pertencem à conta e para listar essas agendas. A autorização fica só na memória desta sessão. <a href="https://github.com/Sosoft142/Retomar/blob/main/GOOGLE_AGENDA.md" target="_blank" rel="noopener noreferrer">Ver instruções completas</a>.</p></details><div class="field"><label for="calendar-client-id">ID público do cliente OAuth</label><input id="calendar-client-id" maxlength="220" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="123456789012-…apps.googleusercontent.com" value="${esc(c.clientId)}"><small class="field-help">Necessário apenas para o envio direto com cores.</small></div><div class="dialogactions"><button class="btn secondary" type="button" id="cancel-planning-settings">Cancelar</button><button class="btn primary" type="submit">Salvar opções</button></div><p class="field-help save-note">Preferências salvas neste aparelho.</p></form>`);
    const mode=root.querySelector('#calendar-mode'),client=root.querySelector('#calendar-client-id'),defaultTime=root.querySelector('#calendar-default-time'),noTime=root.querySelector('#calendar-no-time'),zone=root.querySelector('#calendar-zone');
    const update=()=>{client.required=mode.value==='direct';defaultTime.disabled=noTime.value!=='defaultTime';defaultTime.required=!defaultTime.disabled;root.querySelectorAll('#calendar-notification,[id^=calendar-color-]').forEach(e=>e.disabled=mode.value!=='direct')};mode.onchange=update;noTime.onchange=update;update();
    root.querySelector('#cancel-planning-settings').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{try{client.setCustomValidity('');zone.setCustomValidity('');if(client.value.trim()&&!validClientId(client.value.trim()))client.setCustomValidity('Cole o ID público completo do cliente OAuth, terminado em .apps.googleusercontent.com.');if(!validZone(zone.value.trim()))zone.setCustomValidity('Informe um fuso válido, por exemplo America/Sao_Paulo.');if(!checkForm(e.target))return;const next=structuredClone(prefs());next.calendar={mode:mode.value,clientId:client.value.trim(),calendarId:root.querySelector('#calendar-target').value,duration:Number(root.querySelector('#calendar-duration').value),undatedTime:noTime.value,defaultTime:defaultTime.value||c.defaultTime,timeZone:zone.value.trim(),notification:root.querySelector('#calendar-notification').value,includeNotes:root.querySelector('#calendar-notes').checked,priorityTitle:root.querySelector('#calendar-priority-title').checked,colors:Object.fromEntries(PRIORITIES.map(p=>[p.id,root.querySelector('#calendar-color-'+p.id).value]))};save(next);session.reset(next.calendar.clientId);closeModal(true);toast('Opções do Google Agenda salvas neste aparelho.');onOpen?.(false);if(next.calendar.mode==='direct')session.prepare().catch(()=>{})}catch(error){root.querySelector('.formerror').textContent=error.message}});
  }
  async function connect(){if(!validClientId(prefs().calendar.clientId)){calendarSettings();return}if(!session.snapshot().ready){await session.prepare();toast('Conexão preparada. Toque novamente em Conectar ao Google.');return}await session.connect(prefs().calendar.clientId);try{calendars=await google.calendars()}catch(error){toast(error.message);return}refresh();toast('Google conectado. Você pode escolher a agenda em Configurar adições.')}
  async function send(id){const state=getState(),t=state.items[id];if(!t||t.deleted){toast('Este item não está disponível.');return}if(!t.date){toast('Defina uma data e salve o item antes de enviar ao Google Agenda.');onEdit(id);return}const config=structuredClone(prefs().calendar);
    if(config.mode==='web'){const url=calendarTemplate(state,id,config,appUrl);target.open(url,'_blank','noopener,noreferrer');toast('Evento preparado. Confirme em Salvar no Google Agenda. A cor é escolhida no Google neste modo.');return}
    if(busy.has(id))return;busy.add(id);refresh();try{const event=calendarEvent(state,id,config,appUrl);if(!session.snapshot().ready){await session.prepare();toast('Conexão preparada. Toque novamente no calendário do item para autorizar e enviar.');return}if(!session.token())await session.connect(config.clientId);const current=getState().items[id];if(!current||current.deleted||JSON.stringify(current.revision)!==JSON.stringify(t.revision))throw Error('O item mudou durante a conexão. Confira os dados e toque novamente para enviar.');const result=await google.upsert(config.calendarId,event);toast(result.updated?'Evento atualizado e confirmado no Google Agenda.':'Evento adicionado e confirmado no Google Agenda.',result.link?{label:'Abrir',run:()=>target.open(result.link,'_blank','noopener,noreferrer')}:undefined)}finally{busy.delete(id);refresh()}}
  function refresh(){const bell=target.document.querySelector('.reminder-trigger');if(bell)bell.outerHTML=header();const summary=target.document.querySelector('#planning-summary');if(summary)summary.innerHTML=summaryContent();const result=target.document.querySelector('#reminders-results');if(result&&!target.document.activeElement?.closest('#reminders-results'))result.innerHTML=reminderRows();for(const node of target.document.querySelectorAll('[data-google-message]'))node.textContent=connectionMessage();const s=session.snapshot();for(const b of target.document.querySelectorAll('[data-google-connect]')){b.disabled=['loading','authorizing'].includes(s.phase);b.textContent=s.connected?'Reconectar ao Google':s.phase==='loading'?'Preparando…':'Conectar ao Google'}for(const b of target.document.querySelectorAll('[data-google-disconnect]'))b.hidden=!s.connected;for(const b of target.document.querySelectorAll('[data-action=planning-calendar][data-id]')){b.disabled=busy.has(b.dataset.id);b.setAttribute('aria-busy',String(busy.has(b.dataset.id)))}}
  function reload(){const oldClient=prefs().calendar.clientId;preferences.reload();if(oldClient!==prefs().calendar.clientId){session.reset(prefs().calendar.clientId);calendars=[]}refresh()}
  const storageChanged=e=>{if(e.key===PLANNING_KEY){reload();if(!target.document.querySelector('dialog[open]'))onOpen?.(false)}};
  async function action(name,data){try{if(name==='planning-open'){visible=60;onOpen(true)}else if(name==='planning-reminder-settings')reminderSettings();else if(name==='planning-calendar-settings'){if(busy.size)throw Error('Conclua ou cancele o envio antes de alterar suas opções.');calendarSettings()}else if(name==='planning-connect')await connect();else if(name==='planning-disconnect'){if(busy.size)throw Error('Conclua ou cancele o envio antes de desconectar.');session.disconnect();calendars=[];refresh();toast('Google desconectado neste aparelho.')}else if(name==='planning-calendar')await send(data.id);else if(name==='planning-edit')onEdit(data.id);else if(name==='planning-complete')await onComplete(data.id);else if(name==='planning-snooze'||name==='planning-dismiss'){const t=getState().items[data.id];if(!t||t.deleted||!openItem(t))return;const before=structuredClone(prefs());save(postpone(prefs(),t,now(),name==='planning-dismiss'));const result=target.document.querySelector('#reminders-results');if(result)result.innerHTML=reminderRows();toast(name==='planning-dismiss'?'Aviso dispensado por hoje. A tarefa permanece no planejamento.':'Aviso adiado neste aparelho.',{label:'Desfazer',run:()=>{try{const next=structuredClone(prefs());if(before.dismissals[data.id])next.dismissals[data.id]=before.dismissals[data.id];else delete next.dismissals[data.id];save(next);if(result?.isConnected)result.innerHTML=reminderRows()}catch(e){toast(e.message)}}})}else if(name==='planning-more'){visible+=60;const result=target.document.querySelector('#reminders-results');if(result)result.innerHTML=reminderRows()}}catch(error){toast(error.message)}
  }
  return {header,summary,page,settings,calendarButton,action,refresh,reload,start(){target.addEventListener('storage',storageChanged);if(prefs().calendar.mode==='direct')session.prepare().catch(()=>{});timer=target.setInterval(()=>{if(!target.document.hidden&&!target.document.querySelector('dialog[open]')&&!target.document.documentElement.classList.contains('drag-active')&&!target.document.activeElement?.matches('input,textarea,select'))refresh()},30000)},dispose(){target.clearInterval(timer);target.removeEventListener('storage',storageChanged)}};
}
